package api.publica;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.lang.reflect.Proxy;import java.sql.Connection;import java.time.LocalDateTime;import java.util.List;import org.junit.jupiter.api.Test;import dao.ConvocatoriaComunidadDAO;import negocio.*;import servicio.ConvocatoriaComunidadService;
class ConvocatoriaClienteServiceTest {
 private Connection c(){return (Connection)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(p,m,a)->null);}
 private ConvocatoriaComunidad convocatoria(long cliente){ConvocatoriaComunidad v=new ConvocatoriaComunidad();v.setId(5);v.setReservaId(9);v.setClienteCreadorId(cliente);v.setPerfilCreadorId(4);v.setParticipantesConfirmados(3);v.setLugaresBuscados(1);v.setEstado(EstadoConvocatoriaComunidad.ABIERTA);v.setFechaPublicacion(LocalDateTime.now());v.setFechaExpiracion(LocalDateTime.now().plusDays(1));return v;}
 @Test void listaSoloConvocatoriasDelCliente(){var operaciones=mock(ConvocatoriaComunidadService.class);var dao=mock(ConvocatoriaComunidadDAO.class);when(dao.listarPorCliente(any(),eq(2L))).thenReturn(List.of(convocatoria(2)));var s=new ConvocatoriaClienteService(operaciones,dao,this::c);var r=s.listar(2);assertEquals(1,r.total());assertEquals(1,r.convocatorias().getFirst().lugaresDisponibles());verify(dao).listarPorCliente(any(),eq(2L));}
 @Test void buscarReservaAjenaNoExponeDatos(){var dao=mock(ConvocatoriaComunidadDAO.class);when(dao.buscarActivaPorReserva(any(),eq(9L),eq(false))).thenReturn(convocatoria(8));var s=new ConvocatoriaClienteService(mock(ConvocatoriaComunidadService.class),dao,this::c);assertThrows(ConvocatoriaComunidadService.ReservaAjenaONoEncontradaException.class,()->s.buscarPorReserva(2,9));}
 @Test void publicaMapeandoEntradaSegura(){var operaciones=mock(ConvocatoriaComunidadService.class);var v=convocatoria(2);when(operaciones.publicar(eq(2L),any())).thenReturn(v);var s=new ConvocatoriaClienteService(operaciones,mock(ConvocatoriaComunidadDAO.class),this::c);var r=s.publicar(2,9,new ConvocatoriaClienteDTO.Publicar(3,1,61L,"REVES","Falta una persona"));assertEquals(5,r.convocatoriaId());assertTrue(r.activa());verify(operaciones).publicar(eq(2L),argThat(x->x.reservaId()==9&&x.participantesConfirmados()==3));}
 @Test void cierreUsaMotivoSeguro(){var operaciones=mock(ConvocatoriaComunidadService.class);var v=convocatoria(2);v.setEstado(EstadoConvocatoriaComunidad.CERRADA_EXTERNAMENTE);when(operaciones.cerrarExternamente(2,5,MotivoCierreConvocatoria.JUGADOR_ENCONTRADO_EXTERNAMENTE)).thenReturn(v);var s=new ConvocatoriaClienteService(operaciones,mock(ConvocatoriaComunidadDAO.class),this::c);var r=s.cerrar(2,5,new ConvocatoriaClienteDTO.Cerrar(null));assertFalse(r.activa());assertFalse(r.puedeCerrar());}
}
